import androidx.compose.runtime.DisposableEffect
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateMapOf
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.RectangleShape
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.navigation.NavController
import com.google.firebase.firestore.FirebaseFirestore

/**
 * Documentation generated by Gemini
 * Composable screen for administrator notification delivery log auditing with title/message search and multi-select type filter.
 *
 * @param navController Navigation controller for routing back to admin dashboard.
 */
@Composable
fun AdminNotificationLogScreen(navController: NavController) {
    var notifications by remember { mutableStateOf<List<NotificationItem>>(emptyList()) }
    var isLoading by remember { mutableStateOf(true) }
    var searchQuery by remember { mutableStateOf("") }
    var showFilterDialog by remember { mutableStateOf(false) }
    val selectedTypes = remember { mutableStateMapOf<String, Boolean>() }

    val buttonColor = Color(0xFF283618)
    val cardBg = Color(0xFFFEFAE0)

    DisposableEffect(Unit) {
        val listener = FirebaseFirestore.getInstance()
            .collection("notifications")
            .addSnapshotListener { snapshot, error ->
                if (error != null) {
                    isLoading = false
                    return@addSnapshotListener
                }
                val items = snapshot?.documents?.mapNotNull { doc ->
                    doc.toObject(NotificationItem::class.java)
                }?.sortedByDescending { it.timestamp } ?: emptyList()

                notifications = items
                isLoading = false
            }

        onDispose { listener.remove() }
    }

    val availableTypes = remember(notifications) {
        notifications.map { it.type }.distinct().sorted()
    }

    val filteredNotifications = remember(notifications, searchQuery, selectedTypes.toMap()) {
        val activeTypes = selectedTypes.filter { it.value }.keys
        notifications.filter { notif ->
            val matchesSearch = if (searchQuery.isBlank()) true else {
                val q = searchQuery.trim().lowercase()
                notif.title.lowercase().contains(q) || notif.message.lowercase().contains(q)
            }
            val matchesType = if (activeTypes.isEmpty()) true else notif.type in activeTypes
            matchesSearch && matchesType
        }.sortedByDescending { it.timestamp }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .statusBarsPadding()
            .padding(16.dp)
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.Absolute.Left
        ) {
            Button(
                onClick = { navController.popBackStack() },
                shape = RectangleShape,
                colors = ButtonDefaults.buttonColors(containerColor = buttonColor, contentColor = Color.White)
            ) {
                Text("< Back")
            }
        }

        Spacer(modifier = Modifier.height(16.dp))
        Text("Admin Notification Logs", fontSize = 24.sp, style = MaterialTheme.typography.headlineSmall)
        Spacer(modifier = Modifier.height(12.dp))

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            OutlinedTextField(
                value = searchQuery,
                onValueChange = { searchQuery = it },
                label = { Text("Search title or message...") },
                singleLine = true,
                modifier = Modifier.weight(1f)
            )

            Button(
                onClick = { showFilterDialog = true },
                shape = RectangleShape,
                colors = ButtonDefaults.buttonColors(containerColor = buttonColor, contentColor = Color.White)
            ) {
                Text("Filter")
            }
        }

        Spacer(modifier = Modifier.height(12.dp))

        when {
            isLoading -> {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    CircularProgressIndicator()
                }
            }

            filteredNotifications.isEmpty() -> {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Text(
                        if (notifications.isEmpty()) "No system notification logs recorded."
                        else "No notifications match your search/filter.",
                        fontSize = 16.sp
                    )
                }
            }

            else -> {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f)
                ) {
                    items(filteredNotifications, key = { it.notificationId.ifBlank { it.timestamp.time.toString() + it.userId } }) { notification ->
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 6.dp),
                            colors = CardDefaults.cardColors(
                                containerColor = buttonColor,
                                contentColor = cardBg
                            )
                        ) {
                            Column(modifier = Modifier.padding(16.dp)) {
                                Text(
                                    text = "[${notification.type}] ${notification.title}",
                                    fontSize = 18.sp,
                                    style = MaterialTheme.typography.titleMedium,
                                    color = cardBg
                                )
                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    text = "Recipient User ID: ${notification.userId}",
                                    fontSize = 14.sp,
                                    color = cardBg.copy(alpha = 0.9f)
                                )
                                if (notification.ownerId.isNotBlank()) {
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = "Owner ID: ${notification.ownerId}",
                                        fontSize = 12.sp,
                                        color = cardBg.copy(alpha = 0.8f)
                                    )
                                }
                                if (notification.campsiteId.isNotBlank()) {
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = "Campsite ID: ${notification.campsiteId}",
                                        fontSize = 12.sp,
                                        color = cardBg.copy(alpha = 0.8f)
                                    )
                                }
                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    text = notification.message,
                                    fontSize = 14.sp,
                                    color = cardBg
                                )
                                Spacer(modifier = Modifier.height(8.dp))
                                Text(
                                    text = dateLongUIFormat(notification.timestamp),
                                    fontSize = 12.sp,
                                    color = cardBg.copy(alpha = 0.8f)
                                )
                            }
                        }
                    }
                }
            }
        }
    }

    if (showFilterDialog) {
        AlertDialog(
            onDismissRequest = { showFilterDialog = false },
            title = { Text("Filter Notification Types") },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    if (availableTypes.isEmpty()) {
                        Text("No notification types available.")
                    } else {
                        availableTypes.forEach { typeName ->
                            val isChecked = selectedTypes[typeName] == true
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable {
                                        selectedTypes[typeName] = !isChecked
                                    },
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Text(typeName)
                                Checkbox(
                                    checked = isChecked,
                                    onCheckedChange = { checked ->
                                        selectedTypes[typeName] = checked
                                    }
                                )
                            }
                        }
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = { showFilterDialog = false },
                    colors = ButtonDefaults.buttonColors(containerColor = buttonColor, contentColor = Color.White)
                ) {
                    Text("Apply")
                }
            },
            dismissButton = {
                TextButton(onClick = {
                    selectedTypes.clear()
                    showFilterDialog = false
                }) {
                    Text("Clear All")
                }
            }
        )
    }
}
